import sys

def main():
    n = int(sys.stdin.readline())
    res = set()
    for x in range(10):
        for y in range(10):
            stack = []
            if x != 0:
                stack.append(x)
            if y != 0 and y != x:
                stack.append(y)
            while stack:
                v = stack.pop()
                if v > n:
                    continue
                res.add(v)
                for d in (x, y):
                    nv = v * 10 + d
                    if nv <= n:
                        stack.append(nv)
    print(len(res))

main()
